DebtorPortal = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=DebtorPortal]");

        var buildInfo = {
            "SourceAppId": 0,
            "App": {
                "Name": "",
                "DefaultTheme": "Default",
                "DefaultCultureId": "",
                "Config": {
                    "B2B": {
                        "SourceSystem": "",
                        "TransactionSource": ""
                    },
                    "Components": {
                        "Grids": {
                            "Details": "Expand,Link"
                        }
                    },
                    "Calendars": {
                        "primary": 1
                    }
                }
            }
        }
        var data = await api.get("ContentManagement/App");
        $("[name=templateapp]", container).kendoDropDownList({
            optionLabel: "[resource_displayname[Template]]",
            dataTextField: "Name",
            dataValueField: "Id",
            dataSource: data.value
        }).data("kendoDropDownList");
        buildInfo = new kendo.observable(buildInfo);
        kendo.bind($("[name=DebtorBuilder]", container), buildInfo);
        $("[name=builder]", container).data("model", model);
        $("button[name=submit]", container).on("click", function (e) {
            DebtorPortal.submit(app, buildInfo, container);
        });
        ThemeBuilder.init(app, $(".component[name=ThemeBuilder]", container));
    },

    submit(theApp, buildInfo, container) {
        var app = buildInfo.App;
        var domain = window.location.hostname;
        app.Domain = app.Name + "." + domain;
        app.Config.Themes = {
            "Default": ThemeBuilder.build($("[name=ThemeBuilder]", container))
        };
        var debtorPortalFunctions = {
            [dms[Scripts/AppCreation/DebtorPortal.js]]
        };

        var d = new Dialog({
            width: 800,
            height: 500
        });
        d.init(() => {
            loadComponent($(d.element), "ScriptRunner", (component) => {
                component.init(theApp, d.element, buildInfo, debtorPortalFunctions, d);
            });
        });


        //execute(buildInfo, debtorPortalFunctions);
    }
}
